package com.ruoyi.lottery.controller;
import com.ruoyi.common.config.RuoYiConfig;import com.ruoyi.common.core.domain.AjaxResult;import com.ruoyi.common.utils.file.*;import com.ruoyi.lottery.service.ImageUploadPolicy;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;
@RestController @RequestMapping("/lottery/admin") @PreAuthorize("@ss.hasRole('admin')") public class LotteryUploadController {private final ImageUploadPolicy policy=new ImageUploadPolicy();@PostMapping("/upload-image")public AjaxResult upload(@RequestParam MultipartFile file)throws Exception{byte[] data=file.getBytes();policy.validate(file.getOriginalFilename(),file.getContentType(),data,data.length);String path=FileUploadUtils.upload(RuoYiConfig.getUploadPath(),file,new String[]{"jpg","jpeg","png"});AjaxResult r=AjaxResult.success("上传成功");r.put("url",path);return r;}}
